 * - Erro `unhandled`: sem `detail`, sem `data`, sem `body` (RF-05).
 */
export function toProblemDetails(error: HTTPError, debug?: boolean): ProblemDetails;

/** Frase padrão de status (IANA). Usada quando `statusText` está ausente (D-04). */
